paths:
// !!!! Note: If we modify "Pictures" here with "DoliDroid", then when
// selecting a file qualified for camera input (like the user photo),
// the selector to choose camera is not enabled.

// store in public directory for sharing. Associate with getExternalStorageDirectory
// file path will be storage/emulated/0/The Path/
// Use not recommended by Google


// store in Android app package name directory. Associate with getExternalFilesDir
// file path will be storage/emulated/0/Android/data/com.example.ex/files/The Path/
// Used by DoliDroid to store a downloaded file
// Removed when app is uninstalled


// store in root directory. Cannot access without root. Associate with getFilesDir
// file path will be storage/data/user/0/Android/data/com.example.ex/files/The Path/
// not visible from a file explorer or USB access from desktop.
// Removed when app is uninstalled


// DoliDroid also uses this path to store some data:
// Used by DoliDroid for clear file getApplicationContext().getFilesDir()+"dolidroid_pref"
// Used also to store getApplicationContext().getFilesDir()+"/../shared_prefs/secret_shared_prefs.xml"
